<?php echo form_open(get_uri('fiscal/series/save'),['id'=>'series-form','class'=>'general-form']); ?><div class="modal-body"><input type="hidden" name="id" value="<?php echo $model_info->id; ?>"><div class="form-group row"><label class="col-md-3"><?php echo app_lang('fiscal_issuer'); ?></label><div class="col-md-9"><?php echo form_dropdown('issuer_profile_id',$issuers,$model_info->issuer_profile_id,"class='select2 form-control'"); ?></div></div><div class="form-group row"><label class="col-md-3"><?php echo app_lang('document_type'); ?></label><div class="col-md-9"><?php echo form_dropdown('document_type',['ingreso'=>app_lang('fiscal_document_type_ingreso'),'egreso'=>app_lang('fiscal_document_type_egreso'),'pago'=>app_lang('fiscal_document_type_pago')],$model_info->document_type?:'ingreso',"class='select2 form-control'"); ?></div></div><?php foreach([['series',app_lang('fiscal_series_single')],['initial_folio',app_lang('initial_folio')]]as$f){?><div class="form-group row"><label class="col-md-3"><?php echo $f[1]; ?></label><div class="col-md-9"><?php echo form_input(['name'=>$f[0],'value'=>$model_info->{$f[0]}?:($f[0]==='initial_folio'?1:''),'class'=>'form-control']); ?></div></div><?php } ?><?php foreach([['is_default',app_lang('default')],['is_active',app_lang('active')]]as$f){?><div class="form-group row"><label class="col-md-3"><?php echo $f[1]; ?></label><div class="col-md-9"><?php echo form_checkbox($f[0],'1',$model_info->id?(bool)$model_info->{$f[0]}:true,"class='form-check-input'"); ?></div></div><?php } ?></div><div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal"><?php echo app_lang('close'); ?></button><button class="btn btn-primary" type="submit"><?php echo app_lang('save'); ?></button></div><?php echo form_close(); ?><script>$(document).ready(function(){$('#series-form').appForm({onSuccess:function(){location.reload();}});$('#series-form .select2').select2();});</script>
